{
  "name": "Mercury精密运动控制器",
  "name_en": "Mercury Precision Motion Controller",
  "manufacturer": "Physik Instrumente (PI)",
  "description": "这是一款用于精密定位系统的运动控制器，可通过RS-232串口控制实验室中的电机位移台或其他运动机构。它支持电机使能、回零、绝对与相对移动、位置读取以及边缘搜索等功能，常用于光学实验、精密对准和自动化位移控制。",
  "description_en": "This is a motion controller for precision positioning systems, used to control motorized stages or other motion assemblies in the lab via RS-232 serial communication. It supports motor enable/disable, homing, absolute and relative moves, position readback, and edge finding, and is commonly used for optical experiments, precision alignment, and automated positioning.",
  "tag_hints": [
    "motion control",
    "precision positioning",
    "motorized stage",
    "RS-232 serial control",
    "homing",
    "edge finding"
  ],
  "actions": [
    {
      "action_name": "auto-init",
      "description": "初始化运动控制器通信。",
      "description_en": "Initialize communication with the motion controller."
    },
    {
      "action_name": "auto-write",
      "description": "向控制器发送原始命令。",
      "description_en": "Send a raw command to the controller."
    },
    {
      "action_name": "auto-read",
      "description": "读取控制器的原始响应。",
      "description_en": "Read a raw response from the controller."
    },
    {
      "action_name": "auto-get_board_number",
      "description": "获取控制板编号。",
      "description_en": "Get the controller board number."
    },
    {
      "action_name": "auto-motor_on",
      "description": "开启电机驱动。",
      "description_en": "Enable the motor drive."
    },
    {
      "action_name": "auto-motor_off",
      "description": "关闭电机驱动。",
      "description_en": "Disable the motor drive."
    },
    {
      "action_name": "auto-LL",
      "description": "执行LL原生命令。",
      "description_en": "Execute the native LL command."
    },
    {
      "action_name": "auto-set_home",
      "description": "将当前位置设为原点。",
      "description_en": "Set the current position as home."
    },
    {
      "action_name": "auto-go_home",
      "description": "移动到原点位置。",
      "description_en": "Move to the home position."
    },
    {
      "action_name": "auto-get_position",
      "description": "获取当前位置。",
      "description_en": "Get the current position."
    },
    {
      "action_name": "auto-get_channel",
      "description": "获取当前通道或轴号。",
      "description_en": "Get the current channel or axis number."
    },
    {
      "action_name": "auto-set_position",
      "description": "移动到指定绝对位置。",
      "description_en": "Move to a specified absolute position."
    },
    {
      "action_name": "auto-move_relative",
      "description": "按相对位移移动。",
      "description_en": "Move by a relative displacement."
    },
    {
      "action_name": "auto-abort",
      "description": "中止当前运动。",
      "description_en": "Abort the current motion."
    },
    {
      "action_name": "auto-find_edge",
      "description": "执行边缘搜索。",
      "description_en": "Perform an edge-finding operation."
    }
  ]
}

